    try:
        reply = answer(query, zone, limit)
    except MessageError:
        return 3, b"", "MessageError"
    except CNAMEError:
        return 5, b"", "CNAMEError"
    except EncodeError:
        return 5, b"", "EncodeError"
    return 0, reply, None


